def fill_uids(apps, schema_editor):
    Horse = apps.get_model('core', 'Horse')
    for pk in Horse.objects.filter(uid__isnull=True).values_list('pk', flat=True):
        Horse.objects.filter(pk=pk).update(uid=uuid.uuid4())


def ages_to_foaling_years(apps, schema_editor):
    """Age N on a record made in year Y: foaled c. (Y - N), 1 January.

    The record's creation year is the best guess for when the age was
    typed. All existing rows have no country yet, so the northern rule
    applies.
    """
    Horse = apps.get_model('core', 'Horse')
    rows = Horse.objects.filter(age__isnull=False)
    for horse in rows.filter(date_of_birth__isnull=True).only('pk', 'age', 'created_at'):
        made = horse.created_at.date() if horse.created_at else date.today()
        Horse.objects.filter(pk=horse.pk).update(
            date_of_birth=date(made.year - horse.age, 1, 1),
            dob_precision='estimated',
            age=None,
        )
    # A row with both: the date already won everywhere.
    rows.update(age=None)


def foaling_years_to_ages(apps, schema_editor):
    """Undo: the same arithmetic backwards, for the estimated dates only."""
    Horse = apps.get_model('core', 'Horse')
    rows = Horse.objects.filter(dob_precision='estimated', date_of_birth__isnull=False)
    for horse in rows.only('pk', 'date_of_birth', 'created_at'):
        made = horse.created_at.date() if horse.created_at else date.today()
        Horse.objects.filter(pk=horse.pk).update(
            age=max(made.year - horse.date_of_birth.year, 0),
            date_of_birth=None,
        )


def tidy_microchips(apps, schema_editor):
    Horse = apps.get_model('core', 'Horse')
    for horse in Horse.objects.exclude(microchip='').only('pk', 'microchip'):
        tidy = re.sub(r'[\s\-]', '', horse.microchip)
        if tidy != horse.microchip:
            Horse.objects.filter(pk=horse.pk).update(microchip=tidy)



